function createChargeMesh(pos, sign) {
  const color = sign > 0 ? 0xff2222 : 0x2266ff;
  const mat = new THREE.MeshStandardMaterial({ color, metalness: 0.3, roughness: 0.4 });
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.35, 32, 32), mat);
  mesh.position.copy(pos);
  mesh.name = sign > 0 ? 'PositiveCharge' : 'NegativeCharge';
  mesh.userData.charge = sign; // Store charge value
  return mesh;
}

function animate() {
  requestAnimationFrame(animate);
  const now = performance.now();
  const delta = (now - lastTime) / 1000;
  lastTime = now;
  controls.update();
  const t = (now * 0.001 * FIELD_LINE_ANIMATION_SPEED) % 1;
  for (const { mesh, curve, pts, color } of animatedFieldLines) {
    const visiblePoints = [];
    const N = pts.length;
    const maxIdx = Math.floor(t * (N - 1));
    for (let i = 0; i <= maxIdx; i++) visiblePoints.push(pts[i]);
    if (visiblePoints.length > 1) {
      mesh.geometry.dispose();
      mesh.geometry = new THREE.TubeGeometry(new THREE.CatmullRomCurve3(visiblePoints), visiblePoints.length * 2, 0.025, 8, false);
    }
  }
  for (const { curve, color, charges } of animatedArrows) {
    for (const obj of [...scene.children]) {
      if (obj.name === 'FieldArrow') scene.remove(obj);
    }
    for (let i = 1; i < ARROWS_PER_LINE; i++) {
      const tt = ((t + i / ARROWS_PER_LINE) % 1);
      const pt = curve.getPoint(tt);
      const dir = curve.getTangent(tt).normalize();
      const field = calcField(pt, charges);
      const mag = THREE.MathUtils.clamp(field.length(), MIN_FIELD, MAX_FIELD);
      const arrow = createArrow(pt, dir, mag, color);
      scene.add(arrow);
    }
  }
  renderer.render(scene, camera);
}
