function onMouseDown(event) {
  const rect = renderer.domElement.getBoundingClientRect();
  mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

  raycaster.setFromCamera(mouse, camera);
  const intersects = raycaster.intersectObjects(scene.children, true);

  for (const intersect of intersects) {
    const obj = intersect.object;
    if (obj.name === 'PositiveCharge' || obj.name === 'NegativeCharge') {
      draggedCharge = obj;
      dragPlane.setFromNormalAndCoplanarPoint(
        camera.getWorldDirection(dragPlane.normal),
        draggedCharge.position
      );
      break;
    }
  }
}

function onMouseMove(event) {
  if (!draggedCharge) return;

  const rect = renderer.domElement.getBoundingClientRect();
  mouse.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  mouse.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;

  raycaster.setFromCamera(mouse, camera);
  raycaster.ray.intersectPlane(dragPlane, dragPoint);
  draggedCharge.position.copy(dragPoint);

  const charges = [];
  for (const obj of scene.children) {
    if (obj.name === 'PositiveCharge' || obj.name === 'NegativeCharge') {
      charges.push({
        pos: obj.position.clone(),
        q: obj.userData.charge
      });
    }
  }

  addAnimatedFieldVisualization(charges);
  updateForceVectors(charges);
  updateChargeControls();
}

function onMouseUp() {
  draggedCharge = null;
}

