renderer.domElement.addEventListener('mousemove', onMouseMove);
renderer.domElement.addEventListener('mouseup', onMouseUp);

window.updateChargeValue = function(index, value) {
  const charges = [];
  for (const obj of scene.children) {
    if (obj.name === 'PositiveCharge' || obj.name === 'NegativeCharge') {
      charges.push(obj);
    }
  }
  if (charges[index]) {
    const charge = parseFloat(value);
    charges[index].userData.charge = charge;
    const color = charge > 0 ? 0xff2222 : 0x2266ff;
    charges[index].material.color.setHex(color);
    const valueLabel = document.getElementById(`charge${index}Value`);
    if (valueLabel) {
      valueLabel.textContent = `${charge > 0 ? '+' : ''}${charge}`;
    }
    const chargeData = charges.map(obj => ({
      pos: obj.position.clone(),
      q: obj.userData.charge
    }));
    addAnimatedFieldVisualization(chargeData);
    updateForceVectors(chargeData);
    const chargeType = charge > 0 ? "positive" : "negative";
    speak(`Charge ${index + 1} is now ${chargeType} ${Math.abs(charge)} elementary charges`);
    showPopup(`Charge ${index + 1} updated to ${charge > 0 ? '+' : ''}${charge}e`);
  }
};

