/**
 * Creates a Duracell-style battery mesh.
 * @returns {THREE.Group} Battery group
 */
function createBattery() {
  const group = new THREE.Group();
  // Black body
  const bodyGeom = new THREE.CylinderGeometry(0.28, 0.28, 1.3, 48);
  const bodyMat = new THREE.MeshStandardMaterial({ color: 0x222222 });
  const body = new THREE.Mesh(bodyGeom, bodyMat);
  body.position.y = 0;
  body.name = 'BatteryBody';
  group.add(body);
  // Copper top
  const copperGeom = new THREE.CylinderGeometry(0.285, 0.285, 0.32, 48);
  const copperMat = new THREE.MeshStandardMaterial({ color: 0xb87333, metalness: 0.8, roughness: 0.3 });
  const copper = new THREE.Mesh(copperGeom, copperMat);
  copper.position.y = 0.66;
  copper.name = 'BatteryCopperTop';
  group.add(copper);
  // Negative terminal (bottom)
  const negGeom = new THREE.CylinderGeometry(0.13, 0.13, 0.04, 24);
  const negMat = new THREE.MeshStandardMaterial({ color: 0xaaaaaa, metalness: 0.7 });
  const neg = new THREE.Mesh(negGeom, negMat);
  neg.position.y = -0.67;
  group.add(neg);
  // Positive terminal (top)
  const posGeom = new THREE.CylinderGeometry(0.09, 0.09, 0.08, 24);
  const posMat = new THREE.MeshStandardMaterial({ color: 0xdddddd, metalness: 0.9 });
  const pos = new THREE.Mesh(posGeom, posMat);
  pos.position.y = 0.84;
  group.add(pos);
  group.rotation.z = Math.PI / 2;
  group.position.copy(BATTERY_POS);
  group.name = 'Battery';
  return group;
}

/**
 * Animates the switch leverGroup to the ON or OFF position (time-based, non-overlapping).
 * @param {boolean} on - If true, set to ON position; else OFF.
 */
function animateSwitchLever(on) {
  if (isAnimatingLever) return;
  isAnimatingLever = true;
  const duration = 180; // ms
  const start = leverGroup.rotation.z;
  const target = on ? 0 : Math.PI / 4;
  const startTime = performance.now();
  function animate(now) {
    const elapsed = now - startTime;
    const t = Math.min(elapsed / duration, 1);
    // Ease in-out
    const ease = t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
    leverGroup.rotation.z = start + (target - start) * ease;
    if (t < 1) {
      requestAnimationFrame(animate);
    } else {
      leverGroup.rotation.z = target;
      isAnimatingLever = false;
    }
  }
  requestAnimationFrame(animate);
}

