function updateNarrationButtonsPaused() {
  playBtn.disabled = true;
  pauseBtn.disabled = false;
  stopBtn.disabled = false;
  pauseBtn.textContent = '▶️ Resume';
  narrationStatus.textContent = 'Paused';
}
function stopNarration() {
  if (synth.speaking) synth.cancel();
  utterance = null;
  isPaused = false;
  resetNarrationButtons();
}
playBtn.addEventListener('click', () => {
  stopNarration();
  utterance = new SpeechSynthesisUtterance(ohmsLawText);
  utterance.lang = 'en-US';
  utterance.rate = 1.0;
  utterance.pitch = 1.0;
  utterance.onend = resetNarrationButtons;
  utterance.onstart = updateNarrationButtonsPlaying;
  utterance.onpause = updateNarrationButtonsPaused;
  utterance.onresume = updateNarrationButtonsPlaying;
  synth.speak(utterance);
  isPaused = false;
});
pauseBtn.addEventListener('click', () => {
  if (!synth.speaking) return;
  if (!isPaused) {
    synth.pause();
    isPaused = true;
    updateNarrationButtonsPaused();
  } else {
    synth.resume();
    isPaused = false;
    updateNarrationButtonsPlaying();
  }
});
stopBtn.addEventListener('click', stopNarration);
utterance && (utterance.onend = resetNarrationButtons);
// When narration starts, update buttons
synth.onstart = updateNarrationButtonsPlaying;
synth.onend = resetNarrationButtons;
synth.onpause = updateNarrationButtonsPaused;
synth.onresume = updateNarrationButtonsPlaying;

/**
 * Animate current particles along their wire curves based on current (I = V/R).
 * @param {number} deltaTime - Time since last frame in seconds
 */
function animateCurrentParticles(deltaTime) {
  const I = (switchOn ? V / R : 0); // Ohm's law
  // Map current to speed (t units per second):
  // 0A => 0, 1A => 0.25, 5A => 1.0 (t loops in [0,1])
  const speed = I * 0.2;

  // Update particle color and opacity based on current
  const hue = Math.min(I / 5, 0.4); // Blue (0.4) to Red (0.0) based on current
  const opacity = switchOn ? Math.min(I / 2, 1) : 0; // Fade out when switch is off

  for (const { curve, particles } of currentParticles) {
    for (const p of particles) {
      if (switchOn && I > 0.01) {
        p.mesh.visible = true;
        p.t = (p.t + speed * deltaTime) % 1;
        const pos = curve.getPointAt(p.t);
        p.mesh.position.copy(pos);

        // Update material properties
        p.mesh.material.color.setHSL(hue, 1, 0.5);
        p.mesh.material.emissive.setHSL(hue, 1, 0.3);
        p.mesh.material.opacity = opacity;
      } else {
        p.mesh.visible = false;
      }
    }
  }
}

